void AboutToBeDiscarded(content::WebContents* replacement) override {
  if (!owner_ || !owner_->Current() || !web_contents() || !replacement ||
      web_contents()->GetBrowserContext() != owner_->profile_ ||
      replacement->GetBrowserContext() != owner_->profile_) return;
  // This is Chromium's actual replacement for this exact native tab, before
  // publication. Retain its draft identity and logical membership, not a
  // different window's view or a URL-matched record.
  PageIdentity::Transfer(web_contents(), replacement);
  if (auto id = GetRememberedPinnedTabEntryId(*web_contents()))
    RememberPinnedTabEntryId(*replacement, *id);
  if (auto url = GetRememberedPinnedTabEntryUrl(*web_contents()))
    RememberPinnedTabEntryUrl(*replacement, *url);
}

bool AuxOrganizationWindowController::UnloadViewNow(tabs::TabHandle handle) {
  auto* tab = handle.Get();
  if (Protected(tab)) return false;
  const auto live = views_.find(handle);
  if (live == views_.end() || live->second.document_id.empty()) return false;
  const auto logical = live->second.logical_id;
  const auto document = live->second.document_id;
  const auto page = PageIdentity::GetOrCreate(profile_, tab->GetContents());
  const auto alive = weak_.GetWeakPtr();
  if (model_->GetActiveTab() == tab) {
    // A retained page must not immediately reload because it stayed selected.
    // Use this window's existing visible user page, or the real new-tab owner.
    tabs::TabHandle next;
    const auto* organization = Organization(browser_.get());
    if (!organization || organization->blocked() || !ordinary_eligible_) return false;
    for (auto* candidate : *model_) {
      auto* contents = candidate->GetContents();
      if (candidate == tab || !contents || contents->GetBrowserContext() != profile_ ||
          candidate->IsSplit() || IsBookmarkTabExcluded(candidate, model_) ||
          (!candidate->IsPinned() && !ordinary_eligible_.Run(*candidate))) continue;
      const auto* identity = PageIdentity::FromWebContents(contents);
      if (identity && identity->runtime_owned()) continue;
      const auto id = GetRememberedPinnedTabEntryId(*contents).value_or("");
      const auto entry = organization->snapshot().entries.find(id);
      if (entry != organization->snapshot().entries.end() && !entry->second.archived &&
          (entry->second.space_id.empty() || entry->second.space_id == active_space_)) {
        next = candidate->GetHandle(); break;
      }
    }
    if (next.Get()) {
      model_->ActivateTab(next.Get());
    } else {
      NavigateParams params(browser_.get(), GURL(chrome::kChromeUINewTabURL), ui::PAGE_TRANSITION_TYPED);
      params.disposition = WindowOpenDisposition::NEW_FOREGROUND_TAB;
      Navigate(&params);
    }
  }
  if (!alive || !Current()) return false;
  tab = handle.Get();
  const auto current = views_.find(handle);
  if (!tab || model_->GetIndexOfTab(tab) < 0 || model_->GetActiveTab() == tab || Protected(tab) ||
      !tab->GetContents() || current == views_.end() ||
      current->second.logical_id != logical || current->second.document_id != document ||
      GetRememberedPinnedTabEntryId(*tab->GetContents()) != logical ||
      PageIdentity::GetOrCreate(profile_, tab->GetContents()) != page) return false;
  auto* lifecycle = resource_coordinator::TabLifecycleUnitExternal::FromWebContents(tab->GetContents());
  if (!lifecycle) return false;
  const bool discarded = lifecycle->GetTabState() == mojom::LifecycleUnitState::DISCARDED ||
      lifecycle->DiscardTab(mojom::LifecycleUnitDiscardReason::EXTERNAL);
  // Chromium may replace WebContents or discard it in place. Both retain this
  // native tab, history and exact draft identity; neither closes/shared-archives
  // a logical record. Reacquire after synchronous replacement notifications.
  if (!alive || !Current()) return false;
  tab = handle.Get();
  auto* contents = tab ? tab->GetContents() : nullptr;
  auto* current_lifecycle = contents
      ? resource_coordinator::TabLifecycleUnitExternal::FromWebContents(contents) : nullptr;
  const auto* identity = contents ? PageIdentity::FromWebContents(contents) : nullptr;
  const bool retained = discarded && tab && model_->GetIndexOfTab(tab) >= 0 && contents &&
      contents->GetBrowserContext() == profile_ && current_lifecycle &&
      current_lifecycle->GetTabState() == mojom::LifecycleUnitState::DISCARDED &&
      identity && identity->id() == page && GetRememberedPinnedTabEntryId(*contents) == logical;
  if (retained) { QueueReconcile(); Notify(); }
  return retained;
}
